#define ASSIGN_OP 261
#define REL_OP 262
#define INCR_DECR 263
#define NEWLINE 264
#define Define 265
#define Break 266
#define Quit 267
#define Length 268
#define Return 269
#define For 270
#define If 271
#define While 272
#define Sqrt 273
#define Scale 274
#define Ibase 275
#define Obase 276
#define Auto 277
#define Else 278
#define Continue 279
#define Halt 280
